<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import{onMount}from'svelte';
  import{invalidateAll}from'$app/navigation';
  import type{DesignSnapshot,DesignOperation,DesignElement,Measure}from'@schubert/contracts';
  import{calibrateReference,sourcePointToMm,parseMillimetres,targetMeasure,mm,D,worldMatrix,worldPoint,applyMatrix,inverseRigidMatrix,type PlanReference,type SourcePoint}from'@schubert/geometry';
  import{request}from'#lib/client/api.ts';
  import{uploadOriginal}from'#lib/client/uploads.ts';
  let{snapshot,documents=[],referenceId='',disabled=false,onapply,onclose}:{snapshot:DesignSnapshot;documents?:any[];referenceId?:string;disabled?:boolean;onapply:(operations:DesignOperation[],id?:string)=>void;onclose:()=>void}=$props();
  type Segment={axis:'x'|'y'|'control';a:SourcePoint;b:SourcePoint;length:string};
  let dialog:HTMLDialogElement,sourceVersion=$state(''),pageIndex=$state(1),sourceKind:PlanReference['sourceKind']=$state('pdf_plan'),title=$state('Quellplan'),preview:any=$state(null),busy=$state(false),error=$state(''),notice=$state(''),localReferenceId=$state(''),segments:Segment[]=$state([]),capture:'x'|'y'|'control'|'wall'|'opening'=$state('x'),points:SourcePoint[]=$state([]),tolerance=$state(''),orthogonal=$state(false),opacity=$state(.35),height=$state(''),thickness=$state(''),wallId=$state(''),openingWidth=$state(''),openingHeight=$state(''),selectedText=$state(''),importedValue=$state(''),importUnit=$state('mm'),attempts=$state(0),imageWidth=$state(0),imageHeight=$state(0);
  const existing=$derived(snapshot.elements.find(e=>e.id===(localReferenceId||referenceId)&&e.kind==='plan_reference') as PlanReference|undefined);
  const sources=$derived(documents.filter(d=>['application/pdf','image/png','image/jpeg','image/webp','image/tiff'].includes(d.mime_type)));
  const source=$derived(sources.find(d=>(d.version_id??d.id)===sourceVersion));
  const previewUrl=$derived((preview?.document_id&&(preview.previewDocumentVersionId??preview.document_version_id)?'/api/v1/documents/'+preview.document_id+'/download?version='+(preview.previewDocumentVersionId??preview.document_version_id)+'&inline=1':preview?.preview_url)??(existing?.previewDocumentId?`/api/v1/documents/${existing.previewDocumentId}/download?version=${existing.previewDocumentVersionId}&inline=1`:null));
  const originalUrl=$derived(source?`/api/v1/documents/${source.document_id}/download?version=${source.version_id??source.id}&inline=1`:existing?`/api/v1/documents/${existing.sourceDocumentId}/download?version=${existing.sourceDocumentVersionId}&inline=1`:null);
  const walls=$derived(snapshot.elements.filter(e=>e.kind==='wall'));
  onMount(()=>{if(existing){sourceVersion=existing.sourceDocumentVersionId;pageIndex=existing.pageIndex+1;sourceKind=existing.sourceKind;title=existing.label;opacity=existing.opacity;tolerance=existing.calibration.toleranceMm;orthogonal=existing.calibration.orthogonalAxesDeclared;segments=existing.calibration.segments.map(s=>({...s,length:snapshot.measurements[s.lengthMeasureId]?.valueMm??''}));imageWidth=existing.widthPx;imageHeight=existing.heightPx;}dialog.showModal();return()=>dialog.close();});
  $effect(()=>{const id=preview?.job_id,status=preview?.status;if(!id||!['pending','running','retry'].includes(status)||attempts>=15)return;let active=true;const timer=setTimeout(async()=>{try{const next=await request(`/api/v1/planning/source-preview/${id}`,undefined,'GET');if(active){preview=next;attempts++;if(next.status==='completed'||next.status==='available'){imageWidth=next.width;imageHeight=next.height;}}}catch(problem){if(active)error=(problem as Error).message;}},Math.min(20000,3000*1.5**attempts));return()=>{active=false;clearTimeout(timer);};});
  function setSource(){preview=null;localReferenceId='';segments=[];points=[];error='';notice='';const chosen=sources.find(d=>(d.version_id??d.id)===sourceVersion);if(chosen){title=chosen.name??'Quellplan';sourceKind=chosen.mime_type==='application/pdf'?'pdf_plan':'scan';}}
  async function upload(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;error='';busy=true;try{await uploadOriginal(file,'planning_project',snapshot.planningProjectId);notice='Original versioniert abgelegt. Es erscheint hier nach erfolgreicher Dateiprüfung. Bei fehlendem Virenprüfer bleibt es nachvollziehbar in Quarantäne.';await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
  async function loadPreview(){if(!sourceVersion)return;busy=true;error='';attempts=0;try{preview=await request('/api/v1/planning/source-preview',{document_version_id:sourceVersion,page_index:Number(pageIndex)-1});if(preview.width&&preview.height){imageWidth=preview.width;imageHeight=preview.height;}}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
  function capturePoint(event:PointerEvent){if(event.button!==0||disabled||!imageWidth||!imageHeight)return;const rect=(event.currentTarget as SVGSVGElement).getBoundingClientRect(),p={xPx:mm((event.clientX-rect.left)/rect.width*imageWidth),yPx:mm((event.clientY-rect.top)/rect.height*imageHeight)};points=points.length>=2?[p]:[...points,p];}
  function putSegment(){if(points.length!==2)return;const old=segments.find(s=>s.axis===capture);if(!['x','y','control'].includes(capture))return;segments=[...segments.filter(s=>s.axis!==capture),{axis:capture as Segment['axis'],a:points[0],b:points[1],length:old?.length??''}];points=[];}
  function draft(){
    const sourceId=source?.document_id??existing?.sourceDocumentId,sourceHash=preview?.sourceHash??source?.content_hash??existing?.sourceHash;
    const previewVersion=preview?.previewDocumentVersionId??preview?.document_version_id??existing?.previewDocumentVersionId,previewId=preview?.document_id??existing?.previewDocumentId,previewHash=preview?.previewHash??existing?.previewHash;
    if(!sourceId||!sourceHash||!sourceVersion||!previewVersion||!previewId||!previewHash||!imageWidth||!imageHeight)throw new Error('Zuerst eine vollständig erzeugte, hashgebundene PNG-Seitenvorschau laden.');
    const measurements:Record<string,Measure>={},calibrationSegments=segments.map(s=>{const length=parseMillimetres(s.length);if(length===null||new D(length).lte(0))throw new Error('Jede gezeichnete Bezugsstrecke benötigt ihre bekannte positive Länge in mm.');const id=crypto.randomUUID();measurements[id]={...targetMeasure(length),origin:'import',isEstimated:true,evidenceVersionId:sourceVersion};return{axis:s.axis,a:s.a,b:s.b,lengthMeasureId:id};});
    const tol=parseMillimetres(tolerance);if(tol===null||new D(tol).lt(0))throw new Error('Eine konkrete nichtnegative Kontrolltoleranz in mm eingeben. Dies ist keine Fertigungstoleranz.');
    const reference:PlanReference={id:existing?.id??crypto.randomUUID(),label:title,parentId:existing?.parentId??snapshot.frames[0].id,phase:'existing',locked:false,sourceEvidenceVersionIds:[sourceVersion],kind:'plan_reference',transform:existing?.transform??{position:{xMm:'0',yMm:'0',zMm:'0'},rotationDeg:{x:'0',y:'0',z:'0'}},sourceDocumentId:sourceId,sourceDocumentVersionId:sourceVersion,sourceHash,previewDocumentId:previewId,previewDocumentVersionId:previewVersion,previewHash,pageIndex:Number(pageIndex)-1,widthPx:imageWidth,heightPx:imageHeight,sourceKind,calibration:{segments:calibrationSegments,toleranceMm:tol,orthogonalAxesDeclared:orthogonal,reviewStatus:'unreviewed'},opacity};
    const temporary={...snapshot,measurements:{...snapshot.measurements,...measurements},elements:[...snapshot.elements.filter(e=>e.id!==reference.id),reference]};return{reference,measurements,temporary,report:calibrateReference(temporary,reference)};
  }
  function saveReference(){error='';try{const d=draft();const ops:DesignOperation[]=existing?[{type:'set_plan_calibration',elementId:existing.id,calibration:d.reference.calibration,opacity,measurements:d.measurements}]:[{type:'add_element',element:d.reference,measurements:d.measurements}];onapply(ops,d.reference.id);localReferenceId=d.reference.id;notice=d.report.usable?'Kalibrierung als ungeprüfter Importvorschlag gespeichert.':'Referenz gespeichert. Maßhaltige Übernahme bleibt offen: '+d.report.reasons.join(' ');}catch(problem){error=(problem as Error).message;}}
  function localPoint(p:SourcePoint){if(!existing)throw new Error('Zuerst die Referenz und Kalibrierung speichern.');const point=sourcePointToMm(snapshot,existing,p),world=applyMatrix(point,worldMatrix(snapshot,existing.id));return applyMatrix(world,inverseRigidMatrix(worldMatrix(snapshot,snapshot.frames[0].id)));}
  const base=(kind:DesignElement['kind'],label:string)=>({id:crypto.randomUUID(),label,parentId:snapshot.frames[0].id,phase:'existing' as const,locked:false,sourceEvidenceVersionIds:[existing!.sourceDocumentVersionId],kind});
  function adoptWall(){error='';try{if(points.length!==2||!existing)throw new Error('Zwei Wandendpunkte markieren und zuerst eine prüfbare Kalibrierung speichern.');const a=localPoint(points[0]),b=localPoint(points[1]);if(new D(a.xMm).eq(b.xMm)&&new D(a.yMm).eq(b.yMm))throw new Error('Die Wandendpunkte müssen verschieden sein.');const h=height.trim()?parseMillimetres(height):null,t=thickness.trim()?parseMillimetres(thickness):null;if(height.trim()&&h===null||thickness.trim()&&t===null)throw new Error('Wandhöhe und Kernstärke als eindeutige mm-Werte eingeben.');
      const fresh:DesignElement[]=[],nodes=[a,b].map((point,i)=>{const found=snapshot.elements.find(n=>n.kind==='node'&&n.parentId===snapshot.frames[0].id&&new D(n.point.xMm).minus(point.xMm).abs().lte('0.01')&&new D(n.point.yMm).minus(point.yMm).abs().lte('0.01')&&new D(n.point.zMm).minus(point.zMm).abs().lte('0.01'));if(found)return found;const node={...base('node',`Import · Wandknoten ${i+1}`),kind:'node' as const,point};fresh.push(node);return node;}),id=crypto.randomUUID(),heightId=crypto.randomUUID(),coreId=crypto.randomUUID(),lengthId=crypto.randomUUID();
      const imported=(value:string|null):Measure=>({...targetMeasure(value),origin:'import',isEstimated:true,evidenceVersionId:existing!.sourceDocumentVersionId});const length=mm(Math.hypot(Number(b.xMm)-Number(a.xMm),Number(b.yMm)-Number(a.yMm)));
      const wall:DesignElement={...base('wall','Import · Wand'),id,kind:'wall',startNodeId:nodes[0].id,endNodeId:nodes[1].id,heightMeasureId:heightId,coreThicknessMeasureId:coreId,layers:[]};
      const dimension:DesignElement={...base('dimension','Import · ungeprüfte Wandlänge'),kind:'dimension',refs:nodes.map(n=>({elementId:n.id,feature:'point'})),measureId:lengthId,mode:'driving',offsetMm:'0'};
      onapply([...fresh.map(element=>({type:'add_element' as const,element})),{type:'add_element',element:wall,measurements:{[heightId]:imported(h),[coreId]:imported(t),[lengthId]:imported(length)}},{type:'add_element',element:dimension}],id);points=[];notice='Wand mit ungeprüften Importmaßen übernommen. Kontrollieren, separat aufmessen und fachlich bestätigen.';
    }catch(problem){error=(problem as Error).message;}}
  function adoptOpening(){error='';try{if(!existing||points.length!==2)throw new Error('Zwei Endpunkte auf der Bezugswand markieren.');const wall=snapshot.elements.find(e=>e.id===wallId&&e.kind==='wall');if(wall?.kind!=='wall')throw new Error('Eine vorhandene Bezugswand auswählen.');const a=worldPoint(snapshot,wall.startNodeId),b=worldPoint(snapshot,wall.endNodeId),length=Math.hypot(Number(b.xMm)-Number(a.xMm),Number(b.yMm)-Number(a.yMm));if(!length)throw new Error('Die Bezugswand hat keine gültige Länge.');const p=applyMatrix(localPoint(points[0]),worldMatrix(snapshot,snapshot.frames[0].id)),q=applyMatrix(localPoint(points[1]),worldMatrix(snapshot,snapshot.frames[0].id)),ux=(Number(b.xMm)-Number(a.xMm))/length,uy=(Number(b.yMm)-Number(a.yMm))/length,s=[p,q].map(v=>(Number(v.xMm)-Number(a.xMm))*ux+(Number(v.yMm)-Number(a.yMm))*uy),off=mm(Math.min(...s)),width=openingWidth.trim()?parseMillimetres(openingWidth):mm(Math.abs(s[1]-s[0])),h=openingHeight.trim()?parseMillimetres(openingHeight):null;if(width===null||new D(width).lte(0))throw new Error('Die lichte Breite ist noch unbekannt.');
      const allowance=Math.max(Number(existing.calibration.toleranceMm),Number(snapshot.measurements[wall.coreThicknessMeasureId]?.valueMm??0)/2)+.01;if([p,q].some(v=>Math.abs((Number(v.xMm)-Number(a.xMm))*uy-(Number(v.yMm)-Number(a.yMm))*ux)>allowance))throw new Error('Markierte Öffnung liegt nicht auf der ausgewählten Bezugswand.');
      const ids=[crypto.randomUUID(),crypto.randomUUID(),crypto.randomUUID(),crypto.randomUUID()],measurements=Object.fromEntries([off,width,h,'0'].map((v,i)=>[ids[i],{...targetMeasure(v),origin:'import' as const,isEstimated:true,evidenceVersionId:existing!.sourceDocumentVersionId}]));const element:DesignElement={...base('opening','Import · Öffnung'),kind:'opening',wallId:wall.id,openingType:'door',offsetAlongWallMeasureId:ids[0],widthMeasureId:ids[1],heightMeasureId:ids[2],sillHeightMeasureId:ids[3],hingeSide:null,openingDirection:'none'};onapply([{type:'add_opening',element,measurements}],element.id);points=[];notice='Öffnung als ungeprüfter Importvorschlag übernommen. Bandseite und Öffnungsrichtung sind noch offen.';
    }catch(problem){error=(problem as Error).message;}}
  function adoptText(){error='';try{if(!existing||!selectedText.trim())throw new Error('Eine konkrete Quelltextstelle auswählen.');const raw=parseMillimetres(importedValue);if(raw===null)throw new Error('Den erkannten Maßwert abschreiben und seine Einheit ausdrücklich auswählen.');const value=mm(new D(raw).times(importUnit==='m'?1000:importUnit==='cm'?10:1)),id=crypto.randomUUID(),measurement={...targetMeasure(value),origin:'import' as const,isEstimated:true,evidenceVersionId:existing.sourceDocumentVersionId};const element:DesignElement={...base('dimension',`Quelle: ${selectedText.slice(0,200)}`),kind:'dimension',refs:[{elementId:existing.id,feature:'imported_measure_text'}],measureId:id,mode:'driving',offsetMm:'0'};onapply([{type:'add_element',element,measurements:{[id]:measurement}}],element.id);notice='Maßtext mit Quelle als ungeprüfter Vorschlag übernommen. Er ändert kein bestehendes Aufmaß.';}catch(problem){error=(problem as Error).message;}}
</script>

<dialog bind:this={dialog} oncancel={onclose} aria-labelledby="source-title">
  <header><div><span>GRUNDRISS · SKIZZE · BESTANDSFOTO</span><h2 id="source-title">Mit einer belegten Quelle beginnen.</h2></div><button type="button" onclick={onclose} aria-label="Schließen">×</button></header>
  <div class="source-body"><aside>
    <label>Versionierte Originaldatei<select use:searchableSelect={sourceVersion} bind:value={sourceVersion} onchange={setSource} disabled={!!existing}><option value="">Geprüfte Datei auswählen</option>{#if existing&&!sources.some(s=>(s.version_id??s.id)===existing.sourceDocumentVersionId)}<option value={existing.sourceDocumentVersionId}>Gespeicherte historische Quellversion</option>{/if}{#each sources as item}<option value={item.version_id??item.id}>{item.name}</option>{/each}</select></label>
    <label class="upload">Original hinzufügen<input type="file" accept="application/pdf,image/png,image/jpeg,image/webp,image/tiff" onchange={upload} disabled={busy||disabled}/></label><a href="/documents" target="_blank" rel="noreferrer">Dokumentenakte und Dateiprüfung öffnen</a>
    <label>Bezeichnung<input bind:value={title} disabled={!!existing||disabled}/></label><div class="pair"><label>Seite<input type="number" min="1" max="10000" bind:value={pageIndex} disabled={!!existing}/></label><label>Quelle<select use:searchableSelect={sourceKind} bind:value={sourceKind} disabled={!!existing}><option value="pdf_plan">PDF-Grundriss</option><option value="scan">Planscan</option><option value="sketch">Skizze</option><option value="room_photo">Perspektivisches Raumfoto</option></select></label></div>
    <button class="btn" onclick={loadPreview} disabled={!sourceVersion||busy||disabled}>Seitenvorschau und Maßtexte laden</button>
    {#if preview}<p class="status">Vorschau: {preview.status}{(preview.message??preview.last_error)?' · '+(preview.message??preview.last_error):''}</p>{#if ['pending','running','retry'].includes(preview.status)}<p>Der konkrete Importauftrag wird begrenzt nachverfolgt.</p>{/if}{#if attempts>=15}<button class="btn small" onclick={()=>{attempts=0;void loadPreview();}}>Importstatus erneut prüfen</button>{/if}{/if}
    {#if originalUrl}<a data-sveltekit-reload href={originalUrl} target="_blank" rel="noreferrer">Exakte Originalversion ansehen</a>{/if}
    <hr/><h3>Bezug und unabhängige Kontrolle</h3><p>Zwei Endpunkte im Bild markieren. Bekannte Originalmaße in mm eintragen. Bei Verzerrung beide Achsen prüfen.</p>
    <label>Markieren<select use:searchableSelect={capture} bind:value={capture} onchange={()=>points=[]}><option value="x">X-Bezugsstrecke</option><option value="y">Y-Bezugsstrecke</option><option value="control">Unabhängiges Kontrollmaß</option><option value="wall">Wandendpunkte übernehmen</option><option value="opening">Öffnung übernehmen</option></select></label>
    <div class="points">{#each points as point,i}<fieldset><legend>Punkt {i+1} · Rasterpixel</legend><label>X<input bind:value={point.xPx} inputmode="decimal"/></label><label>Y<input bind:value={point.yPx} inputmode="decimal"/></label></fieldset>{/each}<button class="text" onclick={()=>points=[{xPx:'0',yPx:'0'},{xPx:'0',yPx:'0'}]} disabled={disabled}>Punkte per Zahl eingeben</button></div>
    {#if ['x','y','control'].includes(capture)}<button class="btn small" onclick={putSegment} disabled={points.length!==2||disabled}>Strecke zuordnen</button>{/if}
    {#each segments as segment}<div class="segment"><label>{segment.axis==='control'?'Kontrollmaß':segment.axis.toUpperCase()+'-Bezugsmaß'} (mm)<input bind:value={segment.length} inputmode="decimal" placeholder="Bekannte Länge" disabled={disabled}/></label><small>({segment.a.xPx}, {segment.a.yPx}) → ({segment.b.xPx}, {segment.b.yPx}) px</small><button class="text" onclick={()=>segments=segments.filter(s=>s!==segment)} disabled={disabled}>Entfernen</button></div>{/each}
    <label class="check"><input type="checkbox" bind:checked={orthogonal} disabled={disabled}/> X- und Y-Richtung sind laut Quelle rechtwinklig</label><label>Erlaubte Abweichung des Kontrollmaßes (mm)<input bind:value={tolerance} inputmode="decimal" placeholder="Explizite Prüftoleranz" disabled={disabled}/></label><label>Deckkraft im Grundriss<input type="range" min="0" max="1" step=".05" bind:value={opacity} disabled={disabled}/></label>
    <button class="btn primary" onclick={saveReference} disabled={disabled||busy||!previewUrl}>Referenz und Kalibrierung speichern</button>
    {#if existing}{@const report=calibrateReference(snapshot,existing)}<div class="review" class:valid={report.usable}><strong>{report.usable?'Geometrisch kalibrierter Importvorschlag':'Maßhaltigkeit noch offen'}</strong>{#each [...report.reasons,...report.warnings] as item}<p>{item}</p>{/each}</div>{/if}
    {#if capture==='wall'}<hr/><h3>Markierte Wand übernehmen</h3><label>Wandhöhe (mm)<input bind:value={height} inputmode="decimal" placeholder="Offen"/></label><label>Wandkern (mm)<input bind:value={thickness} inputmode="decimal" placeholder="Offen"/></label><button class="btn" onclick={adoptWall} disabled={disabled||!existing||points.length!==2}>Als ungeprüfte Wand übernehmen</button>{/if}
    {#if capture==='opening'}<hr/><h3>Markierte Öffnung übernehmen</h3><label>Bezugswand<select use:searchableSelect={wallId} bind:value={wallId}><option value="">Wand auswählen</option>{#each walls as wall}<option value={wall.id}>{wall.label}</option>{/each}</select></label><label>Abgelesene lichte Breite (mm)<input bind:value={openingWidth} inputmode="decimal" placeholder="Sonst aus markierter Strecke"/></label><label>Lichte Höhe (mm)<input bind:value={openingHeight} inputmode="decimal" placeholder="Offen"/></label><button class="btn" onclick={adoptOpening} disabled={disabled||!existing||points.length!==2}>Als ungeprüfte Öffnung übernehmen</button>{/if}
  </aside><main>
    {#if error}<p class="alert danger" role="alert">{error}</p>{/if}{#if notice}<p class="alert" role="status">{notice}</p>{/if}
    {#if previewUrl&&imageWidth&&imageHeight}<div class="raster"><svg viewBox={`0 0 ${imageWidth} ${imageHeight}`} role="img" aria-label="Quellplan. Zwei Punkte mit dem Zeiger markieren oder links als Rasterkoordinaten eingeben." onpointerdown={capturePoint}><image href={previewUrl} width={imageWidth} height={imageHeight}/>{#each segments as s}<line x1={s.a.xPx} y1={s.a.yPx} x2={s.b.xPx} y2={s.b.yPx} stroke={s.axis==='control'?'#b4782e':'#315c4c'} stroke-width={imageWidth/500}/>{/each}{#each points as p,i}<circle cx={p.xPx} cy={p.yPx} r={imageWidth/120} fill="#fff" stroke="#b05331" stroke-width={imageWidth/700}/><text x={p.xPx} y={Number(p.yPx)-imageWidth/80} font-size={imageWidth/60} fill="#8b3e21">{i+1}</text>{/each}</svg></div><p class="caption">Private Seitenvorschau · Seite {pageIndex} · {imageWidth} × {imageHeight} Pixel · Kalibrierung bleibt ungeprüft.</p>{:else if originalUrl&&source?.mime_type==='application/pdf'}<iframe src={`${originalUrl}#page=${pageIndex}`} title="Versionierter PDF-Quellplan"></iframe><p>Für Punktkalibrierung die gerasterte Seitenvorschau erzeugen. Der PDF-Inhalt bleibt bereits im Original sichtbar.</p>{:else}<div class="empty"><h3>Das Original bleibt Ihr Bezug.</h3><p>Wählen Sie einen Planscan, eine PDF-Seite oder ein Bestandsfoto. Ein Foto ohne belegte Projektion wird als Bildreferenz geführt.</p></div>{/if}
    <section class="text-import"><h3>Erkannte Maßtexte prüfen</h3><p>Erkennung und OCR sind Importvorschläge. Quelle, Einheit und Wert ausdrücklich prüfen; sie bestätigen kein Aufmaß.</p>{#if preview?.textPositions?.length}<div class="recognized">{#each preview.textPositions as text}<button class:selected={selectedText===text.text} onclick={()=>selectedText=text.text}><strong>{text.text}</strong><small>{text.sourceKind??'PDF/OCR'} · ({text.x}, {text.y}) px{typeof text.confidence==='number'?' · Erkennung '+Math.round(text.confidence*100)+' %':''}</small></button>{/each}</div>{/if}<label>Wörtliche Textstelle<input bind:value={selectedText} placeholder="Aus dem Original übernehmen"/></label><div class="pair"><label>Abgelesener Wert<input bind:value={importedValue} inputmode="decimal"/></label><label>Originaleinheit<select use:searchableSelect={importUnit} bind:value={importUnit}><option value="mm">mm</option><option value="cm">cm</option><option value="m">m</option></select></label></div><button class="btn" onclick={adoptText} disabled={disabled||!existing}>Als ungeprüftes Maß übernehmen</button></section>
  </main></div><footer><span>Originale und Quellen werden versioniert. Fertigungsfreigaben erfordern eigene Prüfungen.</span><button class="btn" onclick={onclose}>Zurück zum Plan</button></footer>
</dialog>

<style>
